<form method="POST" action="{{ $project ? route('saas-ops.implementation-projects.update',$project) : route('saas-ops.implementation-projects.store') }}" class="rounded-xl border bg-white p-5 dark:border-slate-800 dark:bg-slate-900">@csrf @if($project) @method('PUT') @endif<div class="grid gap-4 md:grid-cols-2"><select name="school_id" class="rounded-lg dark:bg-slate-950">@foreach($schools as $school)<option value="{{ $school->id }}" @selected(old('school_id',$project?->school_id)==$school->id)>{{ $school->name }}</option>@endforeach</select><input name="title" value="{{ old('title',$project?->title) }}" placeholder="title" class="rounded-lg dark:bg-slate-950"><select name="stage" class="rounded-lg dark:bg-slate-950">@foreach(['lead','demo_scheduled','proposal_sent','agreement','data_collection','configuration','training','pilot','go_live','handover'] as $stage)<option value="{{ $stage }}" @selected(old('stage',$project?->stage)===$stage)>{{ $stage }}</option>@endforeach</select><select name="status" class="rounded-lg dark:bg-slate-950">@foreach(['open','paused','done','cancelled'] as $status)<option value="{{ $status }}" @selected(old('status',$project?->status ?? 'open')===$status)>{{ $status }}</option>@endforeach</select><select name="owner_id" class="rounded-lg dark:bg-slate-950"><option value="">No owner</option>@foreach($users as $user)<option value="{{ $user->id }}" @selected(old('owner_id',$project?->owner_id)==$user->id)>{{ $user->name }}</option>@endforeach</select><input type="date" name="start_date" value="{{ old('start_date',$project?->start_date?->toDateString()) }}" class="rounded-lg dark:bg-slate-950"><input type="date" name="target_go_live_date" value="{{ old('target_go_live_date',$project?->target_go_live_date?->toDateString()) }}" class="rounded-lg dark:bg-slate-950"></div><textarea name="notes" class="mt-4 w-full rounded-lg dark:bg-slate-950" placeholder="notes">{{ old('notes',$project?->notes) }}</textarea><button class="mt-4 rounded-lg bg-lime